package fixture
import ("testing"; "sync"; "fmt")
func TestConcurrentReplay(t *testing.T) { l:=&Ledger{Balances:map[string]int{"a":100,"b":0}}; const n=32; var wg sync.WaitGroup; results:=make(chan error,n); start:=make(chan struct{}); for i:=0;i<n;i++ { wg.Add(1); go func(){ defer wg.Done(); <-start; results<-l.Transfer("same","a","b",1) }() }; close(start); wg.Wait(); close(results); successes:=0; for err:=range results { if err==nil { successes++ } }; if successes!=1 || l.Balances["a"]!=99 || l.Balances["b"]!=1 || !l.Seen["same"] { t.Fatalf("successes=%d ledger=%+v",successes,l) } }
func TestConcurrentBalance(t *testing.T) { l:=&Ledger{Balances:map[string]int{"a":10}}; const n=30; var wg sync.WaitGroup; results:=make(chan error,n); for i:=0;i<n;i++ { wg.Add(1); go func(i int){ defer wg.Done(); results<-l.Transfer(fmt.Sprint(i),"a","b",1) }(i) }; wg.Wait(); close(results); successes:=0; for err:=range results { if err==nil { successes++ } }; if successes!=10 || l.Balances["a"]!=0 || l.Balances["b"]!=10 || len(l.Seen)!=10 { t.Fatalf("successes=%d",successes) } }
